from __future__ import annotations

from typing import Any

from flask import jsonify, request

from test.apps.builders import build_schema, make_flask_app_from_schema
from test.apps.runtime import OpenAPIApp

_BOUNDED_FIELDS: tuple[tuple[str, int, int], ...] = (
    ("username", 3, 30),
    ("title", 5, 80),
    ("description", 10, 200),
)


def planted_bug() -> OpenAPIApp:
    # 422 messages use Laravel's "field must be at least N characters." phrasing
    # so the error-feedback parser can learn the length bounds that gate the 500.
    paths = {
        "/users": {
            "post": {
                "requestBody": {
                    "required": True,
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object",
                                "properties": {
                                    "username": {"type": "string"},
                                    "title": {"type": "string"},
                                    "description": {"type": "string"},
                                    "tags": {"type": "array", "items": {"type": "string"}},
                                },
                                "required": [field for field, _, _ in _BOUNDED_FIELDS],
                            }
                        }
                    },
                },
                "responses": {
                    "422": {"description": "Unprocessable Entity"},
                    "500": {"description": "Server Error"},
                },
            }
        }
    }
    spec = build_schema(paths)
    app = make_flask_app_from_schema(spec)

    @app.route("/users", methods=["POST"])
    def create_user() -> Any:
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            return jsonify({"message": "The given data was invalid.", "errors": {}}), 422
        errors: dict[str, list[str]] = {}
        for field, lo, hi in _BOUNDED_FIELDS:
            value = body.get(field, "")
            if not isinstance(value, str):
                value = ""
            if len(value) < lo:
                errors.setdefault(field, []).append(f"The {field} field must be at least {lo} characters.")
            elif len(value) > hi:
                errors.setdefault(field, []).append(f"The {field} field must not be greater than {hi} characters.")
        if errors:
            return jsonify({"message": "The given data was invalid.", "errors": errors}), 422
        return "", 500

    return OpenAPIApp(spec=spec, server=app, kind="flask")

